package io.jooby;

import org.junit.jupiter.api.Test;
import jakarta.inject.Provider;
import io.jooby.ServiceRegistry.MapBinder;
import io.jooby.ServiceRegistry.MultiBinder;
import io.jooby.exception.RegistryException;
import java.util.HashMap;
import java.util.Collection;
import java.util.ArrayList;

class ServiceRegistrymultiBinder_ProvidergetClassFikaTest {

    @Test
    void testMapOfToMultiBinderToProviderGetClass() {
        ServiceRegistry registry = new ServiceRegistry() {};

        Class<String> keyType = String.class;
        Reified<Integer> valueType = Reified.get(Integer.class);

        MapBinder<String, Integer> binder = registry.mapOf(keyType, valueType);

        Provider<Integer> mockProvider = new Provider<Integer>() {
            @Override
            public Integer get() {
                return 42;
            }
        };

        binder.addBinding("testKey").toProvider(mockProvider);
    }
}

interface ServiceRegistry {
    default <K, V> MapBinder<K, V> mapOf(@NonNull Class<K> keyType, @NonNull Reified<V> valueType) {
        return multiBinder(Reified.map(keyType, valueType.getType()), new MapBinder<>());
    }

    @SuppressWarnings({ "rawtypes", "unchecked" })
    private <P extends Provider> P multiBinder(@NonNull Reified reified, @NonNull P multibinder) {
        ServiceKey<?> key = ServiceKey.key(reified);
        var existing = putIfAbsent(key, multibinder);
        if (existing != null) {
            if (multibinder.getClass().isInstance(existing)) {
                multibinder = ((P) (existing));
            } else {
                throw new RegistryException("Mismatch type for key: " + reified);
            }
        }
        return multibinder;
    }

    default Object putIfAbsent(ServiceKey<?> key, Object value) {
        return null;
    }

    class MapBinder<K, V> extends MultiBinder<V> {
        private HashMap<K, Provider<V>> services;

        private MapBinder() {
            super(new ArrayList<>());
            this.services = new HashMap<>();
        }

        public MapBinder<K, V> addBinding(K key) {
            return this;
        }

        public void toProvider(Provider<V> provider) {
            provider.getClass();
        }
    }

    class MultiBinder<T> {
        private Collection<Provider<T>> services;

        private MultiBinder(Collection<Provider<T>> services) {
            this.services = services;
        }
    }
}

@interface NonNull {}

class Reified<T> {
    public static <T> Reified<T> get(Class<T> type) {
        return new Reified<>();
    }

    public static Reified<?> map(Class<?> keyType, java.lang.reflect.Type valueType) {
        return new Reified<>();
    }

    public java.lang.reflect.Type getType() {
        return Object.class;
    }
}

class ServiceKey {
    public static ServiceKey key(Reified<?> reified) {
        return new ServiceKey();
    }
}

